namespace sv_2ba467178de54ab9ad07abb0bd7793fa.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks which warehouse the current user has selected.
/// Scoped = per circuit on Blazor Server, so each user gets independent state.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public string SelectedWarehouseId { get; private set; } = AvailableWarehouses[0].Id;
    public string SelectedWarehouseName =>
        AvailableWarehouses.First(w => w.Id == SelectedWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_2ba467178de54ab9ad07abb0bd7793fa.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when new data arrives. Polling is driven by
/// the consumer (Dashboard page) so it only runs while the page is visible.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired when alert data changes. Subscribers must wrap StateHasChanged
    /// in InvokeAsync because this fires from a timer thread.
    /// </summary>
    public event Action? OnChange;

    /// <summary>Simulates a database query — returns a random number 0–15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts 10-second polling for the given warehouse. Multiple callers
    /// are ref-counted so polling only stops when all unsubscribe.
    /// </summary>
    public void StartPolling(Func<string> getWarehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount > 1) return; // already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(getWarehouseId, _cts.Token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return;

        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
        _timer = null;
        _cts = null;
    }

    /// <summary>Immediately refreshes the alert count and notifies subscribers.</summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(Func<string> getWarehouseId, CancellationToken ct)
    {
        // Fire once immediately so the UI isn't empty until the first tick.
        await RefreshAsync(getWarehouseId());

        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync(getWarehouseId());
            }
        }
        catch (OperationCanceledException) { /* expected on dispose */ }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

