@page "/"
@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p>Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum levels:
            <span class="badge @(AlertService.CurrentAlertCount > 0 ? "bg-danger" : "bg-success") fs-5">
                @AlertService.CurrentAlertCount
            </span>
        </p>
        <p class="text-muted small">Auto-refreshes every 10 seconds while this page is open.</p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        // Subscribe to warehouse changes — refresh alerts immediately on switch.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        // Subscribe to alert data changes pushed by the polling loop.
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _alertHandler;

        // Start the 10-second polling loop (ref-counted).
        AlertService.StartPolling(() => WarehouseState.SelectedWarehouseId);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnChange -= _alertHandler;
        AlertService.StopPolling();
    }
}

